// TestErrNilKey checks the sentinel error ErrNilKey. A caller matches it
// with errors.Is and reads its message, so it has a message and an
// identity of its own.
func TestErrNilKey(t *testing.T) {
	t.Parallel()

	others := []struct {
		name string
		err  error
	}{
		{"ErrWrongCurve", ecdsap384.ErrWrongCurve},
		{"ErrInvalidPublicKey", ecdsap384.ErrInvalidPublicKey},
		{"ErrOffCurve", ecdsap384.ErrOffCurve},
	}

	t.Run("Error", func(t *testing.T) {
		t.Parallel()

		t.Run("returns a message", func(t *testing.T) {
			t.Parallel()
			assert.NotNil(t, ecdsap384.ErrNilKey, "ErrNilKey is assigned")
			assert.NotEqual(t, ecdsap384.ErrNilKey.Error(), "", "ErrNilKey has a message")
		})

		t.Run("opens the message with the package prefix", func(t *testing.T) {
			t.Parallel()
			assert.HasPrefix(
				t,
				ecdsap384.ErrNilKey.Error(),
				"ecdsap384: ",
				"the message of ErrNilKey opens with the package prefix",
			)
		})

		t.Run("returns a message of its own", func(t *testing.T) {
			t.Parallel()
			for _, other := range others {
				expect.NotEqual(
					t,
					ecdsap384.ErrNilKey.Error(),
					other.err.Error(),
					"ErrNilKey has the message of "+other.name,
				)
			}
		})

		t.Run("opens with the message of no other sentinel", func(t *testing.T) {
			t.Parallel()
			for _, other := range others {
				expect.False(t, strings.HasPrefix(ecdsap384.ErrNilKey.Error(), other.err.Error()),
					"the message of ErrNilKey opens with the message of "+other.name)
			}
		})
	})

	t.Run("errors.Is", func(t *testing.T) {
		t.Parallel()

		t.Run("matches no other sentinel of the package", func(t *testing.T) {
			t.Parallel()
			for _, other := range others {
				expect.ErrorIsNot(t, ecdsap384.ErrNilKey, other.err, "ErrNilKey does not match "+other.name)
			}
		})
	})
}

